function flattenLeaves(nodes, branch) {
  let out = [];
  for (const node of nodes) {
    if (node.children && node.children.length) {
      out = out.concat(flattenLeaves(node.children, branch));
    } else {
      out.push({ id: node.id, label: node.label, branchId: branch.id, branchLabel: branch.label, color: branch.color });
    }
  }
  return out;
}
const LEAVES = MINDMAP.flatMap((b) => flattenLeaves(b.children, b));
const LEAF_BY_ID = Object.fromEntries(LEAVES.map((l) => [l.id, l]));

function fmtDate(iso) {
  const d = new Date(iso);
  return d.toLocaleDateString("de-DE", { day: "2-digit", month: "long", year: "numeric" });
}
function todayISO() {
  return new Date().toISOString();
}
function sessionAvg(ratings) {
  const vals = Object.values(ratings || {}).map((r) => r.stars).filter((v) => typeof v === "number" && v > 0);
  if (!vals.length) return 0;
  return vals.reduce((a, b) => a + b, 0) / vals.length;
}
function latestRatingFor(sessions, leafId, beforeIndex) {
  const end = beforeIndex === undefined ? sessions.length : beforeIndex;
  for (let i = end - 1; i >= 0; i--) {
    const r = sessions[i].ratings?.[leafId];
    if (r && r.stars) return { ...r, sessionIndex: i, date: sessions[i].date };
  }
  return null;
}

/* ---------- Small UI building blocks ---------- */

function Stars({ value, onChange, size = 18, readOnly = false, muted = false }) {
  const [hover, setHover] = useState(0);
  const display = hover || value || 0;
  return (
    <div className={`eb-stars${readOnly ? " eb-stars-readonly" : ""}`}>
      {[1, 2, 3, 4, 5].map((n) => (
        <button
          key={n}
          type="button"
          disabled={readOnly}
          className="eb-star-btn"
          onMouseEnter={() => !readOnly && setHover(n)}
          onMouseLeave={() => !readOnly && setHover(0)}
          onClick={() => !readOnly && onChange && onChange(n)}
          aria-label={`${n} Sterne`}
        >
          <Star
            size={size}
            strokeWidth={1.5}
            fill={n <= display ? (muted ? "#c9c2ab" : "#C08A34") : "none"}
            color={n <= display ? (muted ? "#c9c2ab" : "#C08A34") : "#c9c2ab"}
          />
        </button>
      ))}
    </div>
  );
}

function Trend({ delta }) {
  if (delta === null || delta === undefined) return null;
  if (delta > 0) return <span className="eb-trend eb-trend-up"><TrendingUp size={14} /> +{delta}</span>;
  if (delta < 0) return <span className="eb-trend eb-trend-down"><TrendingDown size={14} /> {delta}</span>;
  return <span className="eb-trend eb-trend-flat"><Minus size={14} /> gleich</span>;
}

/* ---------- Leaf row (used in both overview + retro session) ---------- */

function LeafRow({ leaf, mode, sessions, draftRatings, onRate, onComment }) {
  const prev = latestRatingFor(sessions, leaf.id);
  const [showComment, setShowComment] = useState(false);

  if (mode === "overview") {
    const seq = sessions.map((s) => s.ratings?.[leaf.id]?.stars).filter((v) => !!v);
    const delta = seq.length >= 2 ? seq[seq.length - 1] - seq[seq.length - 2] : null;
    return (
      <div className="eb-leaf-row">
        <div className="eb-leaf-label">{leaf.label}</div>
        <div className="eb-leaf-right">
          <Stars value={prev ? prev.stars : 0} readOnly size={15} />
          <Trend delta={delta} />
        </div>
      </div>
    );
  }

  // retro mode
  const draft = draftRatings[leaf.id] || { stars: 0, comment: "" };
  const dropped = prev && draft.stars > 0 && draft.stars < prev.stars;
  const commentOpen = showComment || dropped || !!draft.comment;

  return (
    <div className={`eb-leaf-row eb-leaf-row-retro${dropped ? " eb-leaf-dropped" : ""}`}>
      <div className="eb-leaf-top">
        <div className="eb-leaf-label">{leaf.label}</div>
        {prev && (
          <div className="eb-leaf-prev">
            zuletzt <Stars value={prev.stars} readOnly size={12} muted />
          </div>
        )}
      </div>
      <div className="eb-leaf-controls">
        <Stars value={draft.stars} onChange={(n) => onRate(leaf.id, n)} size={22} />
        <button type="button" className="eb-comment-toggle" onClick={() => setShowComment((s) => !s)}>
          <MessageCircle size={14} /> {draft.comment ? "Kommentar" : "+ Kommentar"}
        </button>
      </div>
      {dropped && !draft.comment && (
        <div className="eb-hint">Etwas schlechter als letztes Mal – mögt ihr kurz notieren, woran das lag?</div>
      )}
      {commentOpen && (
        <textarea
          className="eb-textarea"
          placeholder="Was ist passiert? Was wollt ihr besser machen?"
          value={draft.comment}
          onChange={(e) => onComment(leaf.id, e.target.value)}
        />
      )}
    </div>
  );
}

/* ---------- Recursive branch tree renderer ---------- */

function NodeChildren({ nodes, mode, sessions, draftRatings, onRate, onComment }) {
  return nodes.map((node) =>
    node.children && node.children.length ? (
      <div className="eb-subgroup" key={node.id}>
        <div className="eb-subgroup-label">{node.label}</div>
        <NodeChildren nodes={node.children} mode={mode} sessions={sessions} draftRatings={draftRatings} onRate={onRate} onComment={onComment} />
      </div>
    ) : (
      <LeafRow
        key={node.id}
        leaf={LEAF_BY_ID[node.id]}
        mode={mode}
        sessions={sessions}
        draftRatings={draftRatings}
        onRate={onRate}
        onComment={onComment}
      />
    )
  );
}

function BranchAccordion({ branch, open, onToggle, mode, sessions, draftRatings, onRate, onComment, ratedCount }) {
  return (
    <div className="eb-branch" style={{ "--branch-color": branch.color }}>
      <button type="button" className="eb-branch-header" onClick={onToggle}>
        <span className="eb-branch-dot" />
        <span className="eb-branch-title">{branch.label}</span>
        {mode === "retro" && (
          <span className="eb-branch-count">{ratedCount}/{flattenLeaves(branch.children, branch).length}</span>
        )}
        <ChevronDown size={18} className={`eb-chevron${open ? " eb-chevron-open" : ""}`} />
      </button>
      {open && (
        <div className="eb-branch-body">
          <NodeChildren nodes={branch.children} mode={mode} sessions={sessions} draftRatings={draftRatings} onRate={onRate} onComment={onComment} />
        </div>
      )}
    </div>
  );
}

